const privateAddressLabel=entity=>{const address=privateAddress(entity);return address.street&&address.houseNumber?[address.postalCode,`${address.street} ${address.houseNumber}`].filter(Boolean).join(', '):entity?.address||'';};
const rangeLabel=(min,max,unit='')=>{const has=v=>v!==null&&v!==undefined&&v!=='';return has(min)&&has(max)?`${num(min)}–${num(max)} ${unit}`.trim():has(min)?`legalább ${num(min)} ${unit}`.trim():has(max)?`legfeljebb ${num(max)} ${unit}`.trim():'Nincs megkötés';};
const lotLabel=entity=>entity?.type==='Ház'&&entity.lotArea?`${num(entity.lotArea)} m² telek`:'';
const hasAttribute=value=>value!==null&&value!==undefined&&value!=='';
