function feedbackScenarioPanel(){if(!hostedTest||!feedbackScenario?.available)return '';return `<section class="panel feedback-scenario" aria-label="Visszajelzés-próba"><h3>Visszajelzés-próba</h3><p>${feedbackScenario.role==='buyer'?'Az első ingatlannál válaszd a Most nem gombot. Rögtön megjelenik a szokásos visszajelzéskérés.':'A keresői tesztfiókkal adott válasz után itt láthatod az eredményt.'}</p><p>Keresői fiók: <strong>${esc(feedbackScenario.buyerEmail)}</strong><br>Eladói fiók: <strong>${esc(feedbackScenario.sellerEmail)}</strong></p><button class="btn btn-outline" data-action="feedback-scenario-reset">Teszt újraindítása</button></section>`;}
async function resetFeedbackScenario(){
 if(busy||!hostedTest||!feedbackScenario?.available||typeof model.resetFeedbackScenario!=='function')return;
 const scenario=feedbackScenario;
 await run(async release=>{
  feedbackScenarioResetting=true;renderVersion++;clearSellerFeedbackUi();resetRecommendations();feed=[];tab='recommended';closeModal();drawWorkspace();
  try{await model.resetFeedbackScenario();if(!release())return;markDiscoveryStale();if(!release.sameView()){feedbackScenarioResetting=false;await render({preserve:true});return;}insightsPropertyId=scenario.propertyId||'';page=scenario.role==='seller'?'insights':'discover';location.hash=page;}
  catch(error){feedbackScenarioResetting=false;release();await render({preserve:true});throw error;}
  feedbackScenarioResetting=false;if(await render({preserve:true})!==false)toast('A visszajelzés-próba újraindult.');
 });
}
