let activeOperation=null,workspaceCacheModel=null,workspaceCacheSession='',workspaceRead=null,workspaceLoading=false,workspaceError='',workspaceNeedsRefresh=false,workspaceDirtyVersion=0,resumeQueued=false,lastWorkspaceResume=0,workspaceWasHidden=false,discoveryReady=true,deferredFeedbackPrompt=null,matchesInitialized=false;
