async function loadLanding(region=''){const request=++landingRequest;landingRegion=region;landingLoading=true;landingError='';drawLanding();try{const data=await fetchLanding(region?{region}:{});if(request!==landingRequest)return;landingData=data;landingRegions=data.regions||[];landingRegion=data.region?.id||'';}catch(error){if(request!==landingRequest)return;landingData=null;landingError=error.message||'Kérjük, próbáld meg újra egy kicsit később.';}finally{if(request===landingRequest){landingLoading=false;drawLanding();}}}
