async function resumeOnboardingSession(event){
 const draft=readOnboardingDraft();invalidateReplacedOnboardingWork(draft);if(!draft)return;
 if(draft.phase==='editing'){if(isOnboarding()&&onboardingRenderedDraft&&onboardingRenderedDraft!==JSON.stringify(draft)){cleanupPublicEditor();document.getElementById('app').innerHTML='';onboardingPage();}return;}
 if(!draft.expectedEmail||onboardingSaving)return;
 if(event?.type==='storage'&&event.key&&![API_CONFIG_KEY,DRAFT_STORAGE_KEY].includes(event.key))return;
 try{const current=getModel();if(!current)return;model=current;if(onboardingSaveError&&event?.type!=='storage')return;await completeOnboardingDraft();}catch(error){authMessage=error.message||'A munkamenet nem tölthető be.';}
}

function authPage(){cleanupPublicEditor();const draft=readOnboardingDraft(),registering=authMode==='register';document.title=`${registering?'Regisztráció':'Bejelentkezés'} · Otthonra`;document.getElementById('app').innerHTML=`<main class="auth-main"><a class="brand" href="#landing" data-action="landing">otthonra.</a><button class="auth-back" data-action="landing">← Vissza a kezdőoldalra</button><div class="notice" style="margin:24px 0">${icon('shield')}<strong>${esc(environmentLabel())}</strong>${hostedTest?' · Kipróbálásra szánt környezet.':''}</div><form class="panel settings-panel" id="hosted-auth-form">${onboardingAuthNotice(draft)}<h1 style="font-size:25px;margin-bottom:12px">${registering?'Hozd létre a fiókodat.':'Jelentkezz be az Otthonrába.'}</h1><p class="detail-copy">${registering?'Tedd közzé, mit kínálsz vagy keresel. Kapcsolat akkor nyílik, ha mindketten érdeklődtök.':'Folytasd ott, ahol abbahagytad: a mentett kereséseid és ingatlanjaid várnak.'}</p>${registering?field('name','Teljes név','','text','required minlength="3" maxlength="100" autocomplete="name"'):''}${field('email','E-mail-cím',draft?.expectedEmail||'','email','required autocomplete="username"')}${field('password','Jelszó','','password','required minlength="10" maxlength="128" autocomplete="'+(registering?'new-password':'current-password')+'"')}${registering?field('phone','Telefonszám (opcionális)','','tel','autocomplete="tel"')+accountTypeSelect():''}<p id="auth-error" role="alert" style="color:#a54332;margin-bottom:16px">${esc(authMessage||initError||'')}</p><button class="btn btn-dark btn-full" type="submit">${registering?'Fiók létrehozása':'Bejelentkezés'}</button><button class="btn btn-outline btn-full" style="margin-top:12px" type="button" data-action="auth-mode" data-mode="${registering?'login':'register'}">${registering?'Már van fiókom':'Új fiókot hozok létre'}</button></form></main>`;document.getElementById('hosted-auth-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const form=e.currentTarget,data=Object.fromEntries(new FormData(form)),button=form.querySelector?.('button[type="submit"]');const submission={form,draftId:draft?.id};authSubmission=submission;if(button)button.disabled=true;busy=true;try{if(draft&&['awaiting-auth','saving'].includes(draft.phase)){const latest=readOnboardingDraft();if(!latest||JSON.stringify(latest)!==JSON.stringify(draft))throw new Error('A piszkozat időközben másik lapon megváltozott. Nyisd meg újra a regisztrációt.');const expected=String(draft.expectedEmail||'').trim().toLowerCase();if(expected&&expected!==String(data.email).trim().toLowerCase())throw new Error('A piszkozat mentéséhez az eredetileg megadott e-mail-címmel jelentkezz be.');saveDraft(prepareDraftForAuth(draft,data.email));}const connected=await connectApi(location.origin,data.email,data.password,registering?{name:data.name,phone:data.phone||'',accountType:data.accountType||'private'}:undefined);if(authSubmission!==submission||document.getElementById('hosted-auth-form')!==form||!['#login','#register'].includes(location.hash))return;model=connected;authMessage='';initError=null;if(await completeOnboardingDraft())return;page='discover';tab='recommended';imageIndex=0;location.hash='discover';await render();}catch(error){if(authSubmission===submission&&error.code!=='AUTH_ATTEMPT_SUPERSEDED'&&document.getElementById('hosted-auth-form')===form&&document.getElementById('auth-error'))document.getElementById('auth-error').textContent=error.message||'A bejelentkezés nem sikerült.';}finally{if(authSubmission===submission){authSubmission=null;busy=false;}if(button)button.disabled=false;}});}

function normalizeFeedbackPrompt(value){return value&&Object.hasOwn(value,'feedbackPrompt')?value.feedbackPrompt:value||null;}
