function openFeedbackPurchase(id,size){const property=state.properties.find(item=>item.id===id);if(!property||property.archived||!FEEDBACK_PACKAGE_SIZES.includes(size))return;const request=globalThis.crypto?.randomUUID?.()||'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const v=Math.floor(Math.random()*16);return(c==='x'?v:(v&3|8)).toString(16);});openModal(`<div class="eyebrow">Visszajelzés kérése</div><h2>${size} visszajelzés · ${size} kredit</h2><p class="modal-description">${esc(property.title)}</p><p>A csomag indításakor ${size} kreditet vonunk le. A visszajelzés-kérés azonnal bekapcsol, és két hétig tart. A hiányzó válaszok után lejáratkor kreditet írunk jóvá.</p>${state.credits<size?`<p class="notice">Ehhez még ${num(size-state.credits)} kreditre van szükséged.</p><div class="modal-actions"><button class="btn btn-outline" data-action="close">Mégse</button><button class="btn btn-dark" data-page="credits">Kreditek feltöltése</button></div>`:`<div class="modal-actions"><button class="btn btn-outline" data-action="close">Mégse</button><button class="btn btn-orange" data-action="feedback-buy" data-id="${esc(id)}" data-size="${size}" data-request="${esc(request)}">Csomag indítása · ${size} kredit</button></div>`}`);}
