 try{await run(async currentSession=>{const result=await model.getPropertyInsights(propertyId,{offset,limit:current.limit});if(!currentSession()||page!=='insights'||propertyId!==insightsPropertyId||expectedVersion!==renderVersion)return;const seen=new Set(current.items.map(item=>item.id));insightsData={...result,feedback:{...result.feedback,items:[...current.items,...result.feedback.items.filter(item=>!seen.has(item.id))]}};drawWorkspace();},{readOnly:true});}finally{if(paginationFlights.get('feedback')===flight)paginationFlights.delete('feedback');}
