window.addEventListener?.('pageshow',refreshOnboardingState);
window.addEventListener?.('pagehide',()=>{onboardingCleanup?.();onboardingCleanup=null;workspaceWasHidden=true;cancelWorkspaceRead();});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){workspaceWasHidden=true;cancelWorkspaceRead();}else{if(workspaceWasHidden){workspaceNeedsRefresh=true;workspaceWasHidden=false;}scheduleWorkspaceRefresh();}});
document.addEventListener('freeze',()=>{workspaceWasHidden=true;cancelWorkspaceRead();});
document.addEventListener('resume',()=>{workspaceNeedsRefresh=true;workspaceWasHidden=false;scheduleWorkspaceRefresh();});
window.addEventListener?.('focus',scheduleWorkspaceRefresh);
window.addEventListener?.('pageshow',()=>{if(workspaceWasHidden){workspaceNeedsRefresh=true;workspaceWasHidden=false;}scheduleWorkspaceRefresh();});
window.addEventListener?.('storage',event=>{if(event?.key===API_CONFIG_KEY){if(!ensureWorkspaceSession())return;scheduleWorkspaceRefresh();}});
window.addEventListener?.('pageshow',()=>{if(isOnboarding()&&!onboardingCleanup){document.getElementById('app').innerHTML='';onboardingPage();}});
window.addEventListener?.('hashchange',()=>{const route=location.hash.slice(1);if(['login','register'].includes(route)&&authMode===route&&document.getElementById('hosted-auth-form'))return;if(titles[route])page=route;render({reuse:true,preserve:true});});
const paymentResult=new URLSearchParams(location.search).get('payment');if(paymentResult)page='credits';
await render();if(paymentResult==='success')toast('Köszönjük! Az egyenleg a fizetés ellenőrzése után frissül.');if(paymentResult==='cancel')toast('A fizetést megszakítottad. Pénzlevonás nem történt.');

let drag=null;
document.addEventListener('pointerdown',e=>{if(page!=='discover'||tab!=='recommended'||busy||document.querySelector('.modal')||e.target.closest('button,a')||!e.target.closest('#candidate'))return;drag={x:e.clientX,y:e.clientY,id:e.pointerId,card:document.getElementById('candidate')};});
document.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dy)>Math.abs(dx)+15){drag.card.style.transform='';drag.card.style.opacity='';drag=null;return;}if(Math.abs(dx)>15){drag.card.style.transform=`translateX(${dx*.35}px) rotate(${dx*.018}deg)`;drag.card.style.opacity=String(Math.max(.5,1-Math.abs(dx)/650));}});
document.addEventListener('pointerup',async e=>{if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;d.card.style.transform='';d.card.style.opacity='';const dx=e.clientX-d.x;if(Math.abs(dx)>95&&Math.abs(dx)>Math.abs(e.clientY-d.y)*1.5)await decide(dx>0);});
document.addEventListener('pointercancel',()=>{if(drag){drag.card.style.transform='';drag.card.style.opacity='';drag=null;}});
